void xorColor(vec2 uv, float beat, out vec4 color) {
    int ibeat = int(beat);

    float size = 30.;
    uv += iTime;
    uv *= size;

    ivec2 ipos = ivec2(uv.x, uv.y);
    int value = abs(ipos.x) ^ abs(ipos.y);

    color = vec4(0.000,0.502,0.169,1.) + 0.1 * (1. - beat + floor(beat));

    if (value % 23 == ibeat % 23 && beat > 16.0)
        color = vec4(1.000,0.918,0.000,1.);

    if (value % 9 == ((ibeat + 1) / 2) % 2 && beat > 32.0)
        color = vec4(0.000,0.702,1.000,1.);

    if (value % 57 == ibeat % 57 && beat > 48.0)
        color = vec4(1.000,0.733,0.000,1.);

    if (value % 42 == ibeat % 42 && beat > 80.0)
        color = vec4(1.000,0.000,0.000,1.);
}

float map(vec3 p) {
    return p.y + 1.;
}

void mainImageSampled( out vec4 color, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    float aspect = iResolution.x / iResolution.y;
    uv -= 0.5;
    uv.y /= aspect;
    //uv += 0.5;

    float beat = iTime * BPM / 60.;

    vec3 ro = vec3(0., 0., -5.);
    vec3 rd = normalize(vec3(uv, 1.));
    float t = 0.;
    float d = 0.;
    color = vec4(0.278,0.000,0.702,1.);

    for (int i = 0; i < 100; i++) {
        vec3 p = ro + t * rd;

        if (beat > 64.)
            p = rotX(PI/2. - 1.1 * smoothstep(0.25, 0.5, 0.5 + 0.5 * sin(iTime / 2.))) * p;
        else
            p = rotX(PI/2.) * p;
        d = map(p);
        if (d < 0.001) {
            xorColor(p.xz, beat, color);
            break;
        }
        if (t > 100.) break;
        t += d;
    }


    color *= smoothstep(0., 16.0, beat);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec4 total = vec4(0.);
    for (int i = -1; i <= 1; i++)
    for (int j = -1; j <= 1; j++)
    {
        vec4 sampled = vec4(0.);
        mainImageSampled(sampled, fragCoord + vec2(i, j));

        total += sampled / 9.;
    }
    fragColor = total;
}
